    fun gain(voice: AccordVoice, profile: AccordAcousticProfile, midi: Int): Double {
        require(Accord.MODEL_VERSION == MODEL_VERSION) { "ACCORD calibration requires regeneration for this model" }
        require(midi in MIN_MIDI..MAX_MIDI) { "ACCORD calibration note out of range" }
        val row = when (voice) {
            AccordVoice.BRUSH -> { require(profile == AccordAcousticProfile.BASE); 0 }
            AccordVoice.WOOD -> { require(profile == AccordAcousticProfile.BASE); 1 }
            AccordVoice.TINE -> when (profile) {
                AccordAcousticProfile.REFERENCE -> 2
                AccordAcousticProfile.SOFT_ATTACK -> 3
                AccordAcousticProfile.BRIGHT_EDGE -> 4
                AccordAcousticProfile.LONG_RING -> 5
                AccordAcousticProfile.BASE -> error("TINE has no BASE acoustic profile")
            }
        }
        return gains[row][midi - MIN_MIDI]
    }
